CREATE TABLE SERVICE_METHOD (
 ID BIGINT NOT NULL AUTO_INCREMENT COMMENT 'Gateway-local numeric primary key',
 UUID CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'Application-generated public method registration UUID',
 SERVICE_NAME VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'Canonical lowercase implemented service name such as core or documents',
 METHOD_NAME VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'Canonical lowercase public operation alias',
 METHOD_HOST VARCHAR(255) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'Origin only; must match deployment-approved service destination',
 METHOD_PATH VARCHAR(512) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'Implemented destination path; never a dispatcher path or user-provided URL',
 METHOD_DESCRIPTION VARCHAR(256) NULL COMMENT 'Operator-facing description without sensitive data',
 METHOD_STATUS CHAR(1) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT 'D' COMMENT 'A for active or D for disabled',
 METHOD_REQUEST_TYPE VARCHAR(8) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'Exact implemented HTTP verb',
 IS_DATATYPE_SENSITIVE BOOLEAN NOT NULL DEFAULT TRUE COMMENT 'Sensitive operations always require explicit session authorization',
 IS_TESTED BOOLEAN NOT NULL DEFAULT FALSE COMMENT 'Operator confirmation of contract and routing verification; not a security certification',
 AUTHORIZATION_POLICY VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT 'SESSION' COMMENT 'SESSION or tightly restricted PUBLIC_DIAGNOSTIC; registry data cannot grant permissions',
 DEVELOPMENT_ONLY BOOLEAN NOT NULL DEFAULT TRUE COMMENT 'Hide the method outside Development',
 BODY_TYPE VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT 'JSON' COMMENT 'NONE, JSON or MULTIPART expected request body',
 MAX_REQUEST_BYTES INT NOT NULL DEFAULT 1048576 COMMENT 'Per-operation upper bound on incoming body bytes',
 TIMEOUT_MS INT NOT NULL DEFAULT 15000 COMMENT 'Bounded total forwarding timeout; no automatic command retry',
 CREATED_BY_UUID CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'User or workload UUID registering the method',
 CREATED_DATETIME DATETIME(6) NOT NULL COMMENT 'UTC registration timestamp',
 UPDATED_BY_UUID CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'User or workload UUID making the last approved change',
 UPDATED_DATETIME DATETIME(6) NOT NULL COMMENT 'UTC last approved change timestamp',
 ROW_VERSION BIGINT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Explicit optimistic concurrency version incremented on every change',
 PRIMARY KEY (ID), UNIQUE KEY UX_SERVICE_METHOD_UUID (UUID),
 UNIQUE KEY UX_SERVICE_METHOD_ROUTE (SERVICE_NAME,METHOD_NAME,METHOD_REQUEST_TYPE),
 CONSTRAINT CK_SERVICE_METHOD_STATUS CHECK (METHOD_STATUS IN ('A','D')),
 CONSTRAINT CK_SERVICE_METHOD_VERB CHECK (METHOD_REQUEST_TYPE IN ('GET','POST','PUT','PATCH','DELETE')),
 CONSTRAINT CK_SERVICE_METHOD_POLICY CHECK (AUTHORIZATION_POLICY IN ('SESSION','PUBLIC_DIAGNOSTIC')),
 CONSTRAINT CK_SERVICE_METHOD_BODY CHECK (BODY_TYPE IN ('NONE','JSON','MULTIPART')),
 CONSTRAINT CK_SERVICE_METHOD_LIMITS CHECK (MAX_REQUEST_BYTES BETWEEN 1 AND 10485760 AND TIMEOUT_MS BETWEEN 500 AND 30000),
 CONSTRAINT CK_SERVICE_METHOD_FLAGS CHECK (IS_TESTED IN (0,1) AND IS_DATATYPE_SENSITIVE IN (0,1) AND DEVELOPMENT_ONLY IN (0,1)),
 CONSTRAINT CK_SERVICE_METHOD_SENSITIVE CHECK (IS_DATATYPE_SENSITIVE = 0 OR AUTHORIZATION_POLICY = 'SESSION'),
 CONSTRAINT CK_SERVICE_METHOD_METADATA CHECK (ROW_VERSION > 0 AND UPDATED_DATETIME >= CREATED_DATETIME)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin COMMENT='Gateway-owned registry of approved implemented service methods; never executable code';

